%[text] # **Strongly nonlinear snap-through example for adaptiveAnalyze**
%[text] A shallow truss passes through limit points that are difficult for a fixed nonlinear strategy. The adaptive analysis changes algorithms and subdivides failed increments without changing the requested displacement path.
%[text] Model:
%[text]   An asymmetric shallow two-bar truss with corotational geometry.
%[text] ![](text:image:24be)
%[text] Comparison:
%[text]   1\. Fine-step Newton analysis used as the numerical reference.
%[text]   2\. Coarse-step ModifiedNewton analysis using adaptiveAnalyze.
%[text]   3\. Independently stored reference values at selected displacements.
%[text] Expected adaptive behavior:
%[text]   \- ModifiedNewton attempts fail near the limit points.
%[text]   \- KrylovNewton and Newton are attempted.
%[text]   \- Some failed displacement increments are subdivided.
%[text] ![](text:image:332d)
clear;
clc;
close all;

opsMAT = OpenSeesMatlab();
ops = opsMAT.opensees;
%%
%[text] ### Analysis parameters
referenceIncrement = -5.0e-4;
referenceSteps = 400;

adaptiveIncrement = -2.5e-2;
adaptiveSteps = 8;

controlNode = 3;
controlDOF = 2;
loadPatternTag = 1;

%%
%[text] ### Fine-step reference analysis
buildShallowTrussModel(ops);

ops.constraints("Plain");
ops.numberer("Plain");
ops.system("BandGeneral");

ops.test("NormDispIncr", 1.0e-12, 50, 0);
ops.algorithm("Newton");
ops.integrator( ...
    "DisplacementControl", ...
    controlNode, controlDOF, referenceIncrement);
ops.analysis("Static");

reference = zeros(referenceSteps + 1, 4);
% Columns:
%   1: horizontal displacement of node 3
%   2: vertical displacement of node 3
%   3: vertical load magnitude
%   4: OpenSees load factor

reference(1, :) = [
    ops.nodeDisp(controlNode, 1), ...
    ops.nodeDisp(controlNode, 2), ...
    ops.getLoadFactor(loadPatternTag), ...
    ops.getLoadFactor(loadPatternTag)];

for step = 1:referenceSteps
    ok = ops.analyze(1);

    if ok ~= 0
        error( ...
            "Reference analysis failed at step %d with code %d.", ...
            step, ok);
    end

    loadFactor = ops.getLoadFactor(loadPatternTag);

    reference(step + 1, :) = [
        ops.nodeDisp(controlNode, 1), ...
        ops.nodeDisp(controlNode, 2), ...
        loadFactor, ...
        loadFactor];
end

%%
%[text] ### Coarse-step adaptive analysis
buildShallowTrussModel(ops);

ops.constraints("Plain");
ops.numberer("Plain");
ops.system("BandGeneral");

% Intentionally restrictive settings make the original ModifiedNewton
% configuration fail near strongly nonlinear portions of the path.
ops.test("NormDispIncr", 1.0e-12, 2, 0);
ops.algorithm("ModifiedNewton");
ops.integrator( ...
    "DisplacementControl", ...
    controlNode, controlDOF, adaptiveIncrement);
ops.analysis("Static");

adaptive = zeros(adaptiveSteps + 1, 4);
% Columns:
%   1: horizontal displacement of node 3
%   2: vertical displacement of node 3
%   3: vertical load magnitude
%   4: adaptiveAnalyze return code

adaptive(1, :) = [
    ops.nodeDisp(controlNode, 1), ...
    ops.nodeDisp(controlNode, 2), ...
    ops.getLoadFactor(loadPatternTag), ...
    0];
for step = 1:adaptiveSteps %[output:group:8056ebbf]
    fprintf( ... %[output:3d179d8d] %[output:5ce2ae88] %[output:88c5cacf] %[output:2c893bae] %[output:0cd6b51b] %[output:8d683ae7] %[output:30b9a7c9] %[output:22c1abad]
        "\n--- Requested outer displacement step %d of %d ---\n", ... %[output:3d179d8d] %[output:5ce2ae88] %[output:88c5cacf] %[output:2c893bae] %[output:0cd6b51b] %[output:8d683ae7] %[output:30b9a7c9] %[output:22c1abad]
        step, adaptiveSteps); %[output:3d179d8d] %[output:5ce2ae88] %[output:88c5cacf] %[output:2c893bae] %[output:0cd6b51b] %[output:8d683ae7] %[output:30b9a7c9] %[output:22c1abad]

    ok = ops.adaptiveAnalyze(1, ... %[output:410cf287] %[output:251586fc] %[output:469e990f] %[output:372ff318] %[output:4548953d] %[output:7a608c12] %[output:8a6f6d27] %[output:52cf7b63]
        "-algorithms", "KrylovNewton", "Newton", ... %[output:410cf287] %[output:251586fc] %[output:469e990f] %[output:372ff318] %[output:4548953d] %[output:7a608c12] %[output:8a6f6d27] %[output:52cf7b63]
        "-subdivision", 0.5, 1.0e-6, 10, ... %[output:410cf287] %[output:251586fc] %[output:469e990f] %[output:372ff318] %[output:4548953d] %[output:7a608c12] %[output:8a6f6d27] %[output:52cf7b63]
        "-limits", 1000, ... %[output:410cf287] %[output:251586fc] %[output:469e990f] %[output:372ff318] %[output:4548953d] %[output:7a608c12] %[output:8a6f6d27] %[output:52cf7b63]
        "-debug"); %[output:410cf287] %[output:251586fc] %[output:469e990f] %[output:372ff318] %[output:4548953d] %[output:7a608c12] %[output:8a6f6d27] %[output:52cf7b63]

    if ok ~= 0
        error( ...
            "Adaptive analysis failed at outer step %d with code %d.", ...
            step, ok);
    end

    adaptive(step + 1, :) = [
        ops.nodeDisp(controlNode, 1), ...
        ops.nodeDisp(controlNode, 2), ...
        ops.getLoadFactor(loadPatternTag), ...
        ok];
end %[output:group:8056ebbf]
%%
%[text] ### Independently stored reference values
% These values were obtained from the fine-step Newton solution using:
%
%   displacement increment = -5.0e-4
%   test tolerance         = 1.0e-12
%   maximum iterations     = 50
%
% Columns:
%   [horizontal displacement, vertical displacement, load factor]

publishedReference = [
     3.60712752838123e-4, -0.025,  2.48201205553051e-1
     6.19158366863243e-4, -0.050,  2.84192774311654e-1
     7.74542441814802e-4, -0.075,  1.77821500993599e-1
     8.26389841308204e-4, -0.100, -6.10622663543834e-16
     7.74542441814889e-4, -0.125, -1.77821500993605e-1
     6.19158366863171e-4, -0.150, -2.84192774311655e-1
     3.60712752838085e-4, -0.175, -2.48201205553024e-1
    -5.96848531392942e-17, -0.200,  0.0
];

%%
%[text] ### Compare the computed reference with the stored values
referenceAtCheckPoints = zeros(adaptiveSteps, 3);

for i = 1:adaptiveSteps
    targetDisplacement = publishedReference(i, 2);

    [~, index] = min(abs(reference(:, 2) - targetDisplacement));

    referenceAtCheckPoints(i, :) = [
        reference(index, 1), ...
        reference(index, 2), ...
        reference(index, 3)];
end

publishedHorizontalError = ...
    referenceAtCheckPoints(:, 1) - publishedReference(:, 1);

publishedLoadError = ...
    referenceAtCheckPoints(:, 3) - publishedReference(:, 3);

maxPublishedHorizontalError = max(abs(publishedHorizontalError));
maxPublishedLoadError = max(abs(publishedLoadError));

%%
%[text] ### Compare adaptive results with the fine-step reference
adaptiveReferenceLoad = interp1( ...
    -reference(:, 2), ...
    reference(:, 3), ...
    -adaptive(:, 2), ...
    "linear");

adaptiveLoadError = adaptive(:, 3) - adaptiveReferenceLoad;

adaptiveReferenceHorizontalDisp = interp1( ...
    -reference(:, 2), ...
    reference(:, 1), ...
    -adaptive(:, 2), ...
    "linear");

adaptiveHorizontalError = ...
    adaptive(:, 1) - adaptiveReferenceHorizontalDisp;

maxAdaptiveLoadError = max(abs(adaptiveLoadError));
maxAdaptiveHorizontalError = max(abs(adaptiveHorizontalError));

%%
%[text] ### Print comparison table

comparisonTable = table( ...
    (0:adaptiveSteps)', ...
    adaptive(:, 2), ...
    adaptive(:, 1), ...
    adaptive(:, 3), ...
    adaptiveReferenceLoad, ...
    adaptiveLoadError, ...
    adaptiveHorizontalError, ...
    'VariableNames', { ...
        'OuterStep', ...
        'VerticalDisplacement', ...
        'HorizontalDisplacement', ...
        'AdaptiveLoad', ...
        'ReferenceLoad', ...
        'LoadError', ...
        'HorizontalDisplacementError'});

fprintf("\n");
fprintf("============================================================\n"); %[output:7a0a39fa]
fprintf(" Adaptive versus fine-step reference\n"); %[output:12c998de]
fprintf("============================================================\n\n"); %[output:73b8f125]
comparisonTable %[output:75317008]

fprintf("Maximum adaptive load error:              %.6e\n", ... %[output:group:1cbb3df0] %[output:537a4750]
    maxAdaptiveLoadError); %[output:group:1cbb3df0] %[output:537a4750]
fprintf("Maximum adaptive horizontal error:        %.6e\n", ... %[output:group:481e1206] %[output:0312cfc7]
    maxAdaptiveHorizontalError); %[output:group:481e1206] %[output:0312cfc7]
fprintf("Maximum stored-reference load error:      %.6e\n", ... %[output:group:495c72cd] %[output:20a5b1d7]
    maxPublishedLoadError); %[output:group:495c72cd] %[output:20a5b1d7]
fprintf("Maximum stored-reference horizontal error: %.6e\n", ... %[output:group:3ea47628] %[output:84bea096]
    maxPublishedHorizontalError); %[output:group:3ea47628] %[output:84bea096]

%%
%[text] ### Numerical checks
assert(all(adaptive(:, 4) == 0), ...
    "At least one adaptive outer step did not complete.");

assert(abs(adaptive(end, 2) + 0.2) < 1.0e-10, ...
    "The adaptive analysis did not reach the target displacement.");

assert(maxPublishedLoadError < 1.0e-8, ...
    "The fine-step solution does not match the stored load references.");

assert(maxPublishedHorizontalError < 1.0e-8, ...
    "The fine-step solution does not match the stored displacement references.");

assert(maxAdaptiveLoadError < 1.0e-7, ...
    "The adaptive load response differs excessively from the reference.");

assert(maxAdaptiveHorizontalError < 1.0e-7, ...
    "The adaptive horizontal response differs excessively from the reference.");

%%
%[text] ### Plot comparison
downwardReferenceDisp = -reference(:, 2);
downwardAdaptiveDisp = -adaptive(:, 2);

figure( ... %[output:30770294]
    "Color", "white", ... %[output:30770294]
    "Name", "adaptiveAnalyze strong nonlinear demonstration", ... %[output:30770294]
    "Position",[100 100 1500 600]); %[output:30770294]

layout = tiledlayout(2, 2, ... %[output:30770294]
    "TileSpacing", "compact", ... %[output:30770294]
    "Padding", "compact"); %[output:30770294]

title(layout, ... %[output:30770294]
    "Asymmetric shallow-truss snap-through response", ... %[output:30770294]
    "FontWeight", "bold"); %[output:30770294]

% Load-displacement response
nexttile([1, 2]); %[output:30770294]

plot( ... %[output:30770294]
    downwardReferenceDisp, reference(:, 3), ... %[output:30770294]
    "-", ... %[output:30770294]
    "Color", [0.10, 0.35, 0.75], ... %[output:30770294]
    "LineWidth", 2.0, ... %[output:30770294]
    "DisplayName", "Fine-step Newton reference"); %[output:30770294]

hold on; %[output:30770294]

plot( ... %[output:30770294]
    downwardAdaptiveDisp, adaptive(:, 3), ... %[output:30770294]
    "o--", ... %[output:30770294]
    "Color", [0.85, 0.20, 0.15], ... %[output:30770294]
    "MarkerFaceColor", [1.00, 0.75, 0.20], ... %[output:30770294]
    "MarkerSize", 7, ... %[output:30770294]
    "LineWidth", 1.5, ... %[output:30770294]
    "DisplayName", "Coarse adaptiveAnalyze"); %[output:30770294]

plot( ... %[output:30770294]
    -publishedReference(:, 2), publishedReference(:, 3), ... %[output:30770294]
    "ks", ... %[output:30770294]
    "MarkerSize", 6, ... %[output:30770294]
    "LineWidth", 1.0, ... %[output:30770294]
    "DisplayName", "Stored reference values"); %[output:30770294]

yline(0.0, ":", "Color", [0.35, 0.35, 0.35]); %[output:30770294]
grid on; %[output:30770294]
box on; %[output:30770294]

xlabel("Downward displacement, -u_y"); %[output:30770294]
ylabel("Load factor"); %[output:30770294]
legend("Location", "bestoutside"); %[output:30770294]

% Horizontal equilibrium response
nexttile; %[output:30770294]

plot( ... %[output:30770294]
    downwardReferenceDisp, reference(:, 1), ... %[output:30770294]
    "-", ... %[output:30770294]
    "Color", [0.10, 0.35, 0.75], ... %[output:30770294]
    "LineWidth", 2.0, ... %[output:30770294]
    "DisplayName", "Reference"); %[output:30770294]

hold on; %[output:30770294]

plot( ... %[output:30770294]
    downwardAdaptiveDisp, adaptive(:, 1), ... %[output:30770294]
    "o", ... %[output:30770294]
    "Color", [0.85, 0.20, 0.15], ... %[output:30770294]
    "MarkerFaceColor", [1.00, 0.75, 0.20], ... %[output:30770294]
    "MarkerSize", 6, ... %[output:30770294]
    "DisplayName", "Adaptive"); %[output:30770294]

grid on; %[output:30770294]
box on; %[output:30770294]

xlabel("Downward displacement, -u_y"); %[output:30770294]
ylabel("Horizontal displacement, u_x"); %[output:30770294]
legend("Location", "bestoutside"); %[output:30770294]

% Adaptive error
nexttile; %[output:30770294]

semilogy( ... %[output:30770294]
    downwardAdaptiveDisp, ... %[output:30770294]
    max(abs(adaptiveLoadError), eps), ... %[output:30770294]
    "o-", ... %[output:30770294]
    "Color", [0.55, 0.15, 0.70], ... %[output:30770294]
    "MarkerFaceColor", [0.75, 0.55, 0.90], ... %[output:30770294]
    "LineWidth", 1.5, ... %[output:30770294]
    "DisplayName", "|load error|"); %[output:30770294]

hold on; %[output:30770294]

semilogy( ... %[output:30770294]
    downwardAdaptiveDisp, ... %[output:30770294]
    max(abs(adaptiveHorizontalError), eps), ... %[output:30770294]
    "s-", ... %[output:30770294]
    "Color", [0.10, 0.55, 0.30], ... %[output:30770294]
    "MarkerFaceColor", [0.45, 0.80, 0.55], ... %[output:30770294]
    "LineWidth", 1.5, ... %[output:30770294]
    "DisplayName", "|horizontal displacement error|"); %[output:30770294]

grid on; %[output:30770294]
box on; %[output:30770294]

xlabel("Downward displacement, -u_y"); %[output:30770294]
ylabel("Absolute error"); %[output:30770294]
legend("Location", "bestoutside"); %[output:30770294]

fprintf("\nAll reference and adaptive comparison checks passed.\n"); %[output:6b9ec3a5]
ops.wipe();
%%
%[text] ### Local function
function buildShallowTrussModel(ops)
%BUILDSHALLOWTRUSSMODEL Create an asymmetric two-bar snap-through model.

ops.wipe();

ops.model("basic", "-ndm", 2, "-ndf", 2);

% Support nodes and shallow apex.
ops.node(1, -1.0, 0.0);
ops.node(2,  1.2, 0.0);
ops.node(3,  0.0, 0.1);

ops.fix(1, 1, 1);
ops.fix(2, 1, 1);
ops.fix(3, 0, 0);

% The material is elastic. Strong nonlinearity is produced by the
% corotational geometry and shallow snap-through configuration.
ops.uniaxialMaterial("Elastic", 1, 1000.0);

ops.element("corotTruss", 1, 1, 3, 1.0, 1);
ops.element("corotTruss", 2, 2, 3, 1.0, 1);

ops.timeSeries("Linear", 1);
ops.pattern("Plain", 1, 1);

% Unit downward reference load. Therefore, the load factor is also the
% magnitude of the applied vertical load.
ops.load(3, 0.0, -1.0);
end

%[text] ### Interpreting the comparison
%[text] The accepted adaptive path should remain close to the fine-step reference through both limit-point regions. The recovery log shows which algorithm changes and subdivisions were required to continue that path.

